// ═══ WRONG: join before launch = SEQUENTIAL! ═══
int balance = supplyAsync(() -> getBalance()).join();      // blocks 200ms!
int score = supplyAsync(() -> getCreditScore()).join();      // blocks 300ms (starts AFTER balance!)
int property = supplyAsync(() -> getPropertyValue()).join(); // blocks 150ms (starts AFTER score!)
// Total: 200 + 300 + 150 = 650ms! SEQUENTIAL!
// Each supplyAsync starts ONLY after the previous join returns!

// ═══ CORRECT: launch all first, join last = PARALLEL! ═══
CF<Integer> balanceCF = supplyAsync(() -> getBalance());       // launched immediately!
CF<Integer> scoreCF = supplyAsync(() -> getCreditScore());      // launched immediately!
CF<Integer> propertyCF = supplyAsync(() -> getPropertyValue()); // launched immediately!
// All three running in PARALLEL right now!

CompletableFuture.allOf(balanceCF, scoreCF, propertyCF).join(); // wait for ALL
int balance = balanceCF.join();    // already done!
int score = scoreCF.join();         // already done!
int property = propertyCF.join();   // already done!
// Total: max(200, 300, 150) = 300ms! PARALLEL!

// ═══ ALSO WRONG: join inside a loop ═══
List<String> results = new ArrayList<>();
for (String id : accountIds) {
    String result = supplyAsync(() -> fetchData(id)).join();  // blocks each iteration!
    results.add(result);
}
// 100 accounts × 200ms each = 20 seconds! SEQUENTIAL!

// ═══ CORRECT: launch all in loop, join after ═══
List<CF<String>> futures = accountIds.stream()
    .map(id -> supplyAsync(() -> fetchData(id), ioPool))
    .toList();  // ALL launched!

List<String> results = futures.stream()
    .map(CompletableFuture::join)  // collect results (all already done!)
    .toList();
// 100 accounts on 50-thread pool: ~400ms! (2 batches × 200ms)
