package com.bank.serial;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class AccidentalSerialTest {

    void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) {} }

    // ═══ WRONG: join before next launch = sequential ═══
    @Test
    void sequential_joinBeforeLaunch() {
        long start = System.currentTimeMillis();

        int a = CompletableFuture.supplyAsync(() -> { sleep(200); return 1; }).join();
        int b = CompletableFuture.supplyAsync(() -> { sleep(200); return 2; }).join();
        int c = CompletableFuture.supplyAsync(() -> { sleep(200); return 3; }).join();

        long elapsed = System.currentTimeMillis() - start;
        assertThat(a + b + c).isEqualTo(6);
        System.out.println("Sequential (wrong): " + elapsed + "ms");
        assertThat(elapsed).isGreaterThanOrEqualTo(500);  // ~600ms! Sequential!
    }

    // ═══ CORRECT: launch all, join last = parallel ═══
    @Test
    void parallel_launchAllJoinLast() {
        long start = System.currentTimeMillis();

        CompletableFuture<Integer> cfA = CompletableFuture.supplyAsync(() -> { sleep(200); return 1; });
        CompletableFuture<Integer> cfB = CompletableFuture.supplyAsync(() -> { sleep(200); return 2; });
        CompletableFuture<Integer> cfC = CompletableFuture.supplyAsync(() -> { sleep(200); return 3; });

        CompletableFuture.allOf(cfA, cfB, cfC).join();
        int sum = cfA.join() + cfB.join() + cfC.join();

        long elapsed = System.currentTimeMillis() - start;
        assertThat(sum).isEqualTo(6);
        System.out.println("Parallel (correct): " + elapsed + "ms");
        assertThat(elapsed).isLessThan(400);  // ~200ms! Parallel!
    }

    // ═══ WRONG: join inside loop = sequential ═══
    @Test
    void sequential_joinInsideLoop() {
        List<Integer> ids = IntStream.range(0, 10).boxed().toList();
        long start = System.currentTimeMillis();

        List<String> results = new ArrayList<>();
        for (int id : ids) {
            results.add(CompletableFuture.supplyAsync(() -> {
                sleep(100); return "DATA-" + id;
            }).join());  // blocks each iteration!
        }

        long elapsed = System.currentTimeMillis() - start;
        assertThat(results).hasSize(10);
        System.out.println("Loop sequential: " + elapsed + "ms");
        assertThat(elapsed).isGreaterThanOrEqualTo(900);  // ~1000ms!
    }

    // ═══ CORRECT: launch all in loop, collect after ═══
    @Test
    void parallel_launchInLoopCollectAfter() {
        List<Integer> ids = IntStream.range(0, 10).boxed().toList();
        long start = System.currentTimeMillis();

        List<CompletableFuture<String>> futures = ids.stream()
            .map(id -> CompletableFuture.supplyAsync(() -> {
                sleep(100); return "DATA-" + id;
            }))
            .toList();

        List<String> results = futures.stream()
            .map(CompletableFuture::join)
            .toList();

        long elapsed = System.currentTimeMillis() - start;
        assertThat(results).hasSize(10);
        System.out.println("Loop parallel: " + elapsed + "ms");
        assertThat(elapsed).isLessThan(500);  // ~100-200ms! Parallel!
    }
}
